'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const { fixture } = require('./native-value-fixture');
// Synthetic point/header transport only. Actual Line/Bar geometry and pixels are generated by the C# contracts.
function native(f, before, after, initial = false) {
  const legacy = JSON.parse(f.transition(before, after));
  return { kind: 'native-transition', effect: initial ? 'initial-values' : 'values', sourceKind: 'cartesian-value', destination: f.make(after).outerHTML,
    readings: [{ seriesKey: 'current', observationId: 'value', fromValue: before, toValue: after, minimum: 0, maximum: 100 }],
    drawings: { wide: { capturePngText: false, sourcePrefix: 'synthetic-source', destinationPrefix: 'synthetic-destination',
      frames: legacy.wide.map((svg, index) => ({ prefix: 'synthetic-cartesian-' + index, svg })) } } };
}
function save(f, name, payload) {
  const output = process.env.CFX_BROWSER_CAPTURE_DIRECTORY; if (!output) return;
  fs.mkdirSync(output, { recursive: true }); fs.writeFileSync(path.join(output, name + '.observed.json'), JSON.stringify({ value: f.source(), revision: f.controller.sceneRevision, changes: f.changes, payload }, null, 2));
  fs.writeFileSync(path.join(output, name + '.transport.html'), f.root.outerHTML);
}
test('existing one-edit Cartesian transport installs final source while its native frames use the same scheduler', () => {
  const f = fixture('cartesian-value'); try {
    const revision = f.controller.sceneRevision, payload = f.transition(20, 80);
    f.controller.update(f.make(80), { sceneRevision: revision, transition: payload, motion: { duration: 1000 } }); save(f, 'cartesian-one-edit', payload);
    assert.equal(f.source(), 80); assert.notEqual(f.controller.sceneRevision, revision); assert.equal(f.changes.length, 1);
    assert.equal(f.root.querySelectorAll('.cfx-native-motion-frame').length, 1); f.controller.resize(); assert.equal(f.root.querySelectorAll('.cfx-native-motion-frame').length, 0);
  } finally { f.close(); }
});
test('captured Cartesian initial values leave the already accepted native source and revision intact', () => {
  const f = fixture('cartesian-value'); try {
    const payload = native(f, 20, 80, true); f.controller.update(payload.destination); const revision = f.controller.sceneRevision, changes = f.changes.length;
    f.controller.presentInitial(JSON.stringify(payload), { sceneRevision: revision, motion: { duration: 1000 } }); save(f, 'cartesian-initial', payload);
    assert.equal(f.source(), 80); assert.equal(f.controller.sceneRevision, revision); assert.equal(f.changes.length, changes);
    assert.equal(f.root.querySelectorAll('.cfx-native-motion-frame').length, 1); f.controller.dispose(); assert.equal(f.root.querySelectorAll('.cfx-native-motion-frame').length, 0);
  } finally { f.close(); }
});
const invalid = {
  foreignAxis: payload => { payload.drawings.wide.frames[1].svg = payload.drawings.wide.frames[1].svg.replace('data-cfx-axis="primary"', 'data-cfx-axis="secondary"'); },
  identity: payload => { payload.drawings.wide.frames[1].svg = payload.drawings.wide.frames[1].svg.replace('data-cfx-observation-id="value"', 'data-cfx-observation-id="foreign"'); },
  firstValue: payload => { payload.drawings.wide.frames[0].svg = payload.drawings.wide.frames[0].svg.replace('data-cfx-y="20"', 'data-cfx-y="21"'); },
  finalValue: payload => { payload.drawings.wide.frames[2].svg = payload.drawings.wide.frames[2].svg.replace('data-cfx-y="80"', 'data-cfx-y="81"'); },
  missingY: payload => { payload.drawings.wide.frames[1].svg = payload.drawings.wide.frames[1].svg.replace('data-cfx-y="50"', ''); },
  domain: payload => { payload.readings[0].maximum = 200; },
  duplicate: payload => { payload.drawings.wide.frames[1].svg = payload.drawings.wide.frames[1].svg.replace('</svg>', '<path id="synthetic-cartesian-1-node-99"/><path id="synthetic-cartesian-1-node-99"/></svg>'); }
};
for (const [name, mutate] of Object.entries(invalid)) test('all-candidate Cartesian preflight rejects ' + name + ' before acceptance and events', () => {
  const f = fixture('cartesian-value'); try {
    const payload = native(f, 20, 80), revision = f.controller.sceneRevision, original = f.root.outerHTML; mutate(payload); save(f, 'cartesian-invalid-' + name, payload);
    assert.throws(() => f.controller.update(payload.destination, { sceneRevision: revision, transition: JSON.stringify(payload), motion: { duration: 1000 } }), f.window.TypeError);
    assert.equal(f.source(), 20); assert.equal(f.controller.sceneRevision, revision); assert.equal(f.changes.length, 0); assert.equal(f.root.outerHTML, original);
  } finally { f.close(); }
});
test('sustained absolute Cartesian updates supersede presentation without creating another frame layer or source queue', () => {
  const f = fixture('cartesian-value'); try {
    let value = 20;
    for (let index = 0; index < 100; index++) { const next = value === 20 ? 80 : 20, payload = native(f, value, next);
      f.controller.update(payload.destination, { sceneRevision: f.controller.sceneRevision, transition: JSON.stringify(payload), motion: { duration: 1000 } }); value = next;
      assert.equal(f.root.querySelectorAll('.cfx-native-motion-frame').length, 1);
    }
    save(f, 'cartesian-sustained', { updates: 100 }); assert.equal(f.source(), value); assert.equal(f.changes.length, 100);
    f.controller.dispose(); assert.equal(f.root.querySelectorAll('.cfx-native-motion-frame,[data-cfx-update-motion]').length, 0);
  } finally { f.close(); }
});
